function inheritedRelationships(data,article,maxDepth=1){if(maxDepth<2)return[];const output=[],walk=(id,path,seen)=>{for(const child of childrenOf(data,id)){if(seen.has(child.id))continue;const nextPath=[...path,child.id],distance=nextPath.length-1;if(distance>=2)output.push({article:child,direction:"child",inherited:true,via:nextPath.at(-2),distance,path:nextPath});if(distance<maxDepth)walk(child.id,nextPath,new Set(seen).add(child.id));}};walk(article.id,[article.id],new Set([article.id]));return output;}
