function searchHtml(data,query,asPlayer=viewerIsPlayer()){const results=searchArticles(data,query,{player:asPlayer});return `<article class="cw-search"><h1>Search</h1><p>${results.length} result(s) for “${esc(query)}”</p>${results.map(result=>`<button data-action="open" data-id="${result.article.id}"><strong>${esc(result.article.title)}</strong><span>${result.match}${result.alias?`: ${esc(result.alias)}`:""}</span></button>`).join("")||'<p class="cw-empty">Nothing found.</p>'}</article>`;}

class CampaignWikiApp extends Application{
  constructor(options={}){super(options);this.currentId=null;this.currentPath=null;this.query="";this.openNavigation=new Set();this.expandedRelationshipGroups=new Set();this.playerPreview=false;}
  static get defaultOptions(){return foundry.utils.mergeObject(super.defaultOptions,{id:"campaign-wiki-app",title:"Campaign Wiki",width:1280,height:800,resizable:true,popOut:true,classes:["campaign-wiki"]});}
  async _renderInner(){const data=database(),asPlayer=this.playerPreview||viewerIsPlayer(),content=this.query?searchHtml(data,this.query,asPlayer):this.currentId?articleHtml(data,data.articles[this.currentId],this.currentPath,this.expandedRelationshipGroups,asPlayer):homeHtml(data,asPlayer),controls=this.playerPreview?'<span class="cw-preview-label"><i class="fas fa-eye"></i> Player Preview</span>'+button("Exit Preview","exit-preview","","fa-times"):game.user.isGM?button("New Article","new-article","","fa-plus")+`<button type="button" data-action="edit" data-id="${this.currentId??""}"${this.currentId?"":" disabled"}><i class="fas fa-edit"></i>Edit Article</button>`:"";return $(`<div class="cw-shell"><aside>${navigation(data,this.openNavigation,asPlayer)}</aside><main><div class="cw-toolbar"><form data-search><input name="query" placeholder="Search Campaign Wiki" value="${esc(this.query)}"><button><i class="fas fa-search"></i></button></form>${controls}</div><div class="cw-content">${content}</div></main></div>`);}
  activateListeners(html){super.activateListeners(html);html.on("click","[data-action]",event=>this.action(event));html.find("details[data-nav-key]").each((_index,details)=>details.addEventListener("toggle",()=>details.open?this.openNavigation.add(details.dataset.navKey):this.openNavigation.delete(details.dataset.navKey)));html.find(".cw-article-of-day-text").each((_index,text)=>{const more=text.nextElementSibling;if(more)more.hidden=text.scrollHeight<=text.clientHeight+1;});html.on("submit","[data-search]",event=>{event.preventDefault();this.query=new FormData(event.currentTarget).get("query");this.currentId=null;this.render(false);});}
  async action(event){event.preventDefault();event.stopPropagation();const {action,id,path,group,src,title}=event.currentTarget.dataset;if(action==="home"){this.currentId=null;this.currentPath=null;this.query="";return this.render(false);}if(action==="breadcrumb-root"){this.currentId=null;this.currentPath=null;this.query="";this.openNavigation.add(`root:${id}`);return this.render(false);}if(action==="open"){this.currentId=id;this.currentPath=path?JSON.parse(path):null;this.query="";return this.render(false);}if(action==="view-image"){const Popout=globalThis.ImagePopout??globalThis.foundry?.applications?.apps?.ImagePopout;if(Popout)return new Popout(src,{title}).render(true);return globalThis.open(src,"_blank","noopener");}if(action==="player-preview"){this.playerPreview=true;return this.render(false);}if(action==="exit-preview"){this.playerPreview=false;return this.render(false);}if(action==="show-relationships"){this.expandedRelationshipGroups.add(`${id}:${group}`);return this.render(false);}if(action==="explain-relationships")return explainRelationships(id);if(action==="new-article")return editArticle();if(action==="edit"&&id)return editArticle(database().articles[id]);if(action==="new-child")return newChild(id);if(action==="delete")return deleteArticle(id);if(action==="open-source")return sourceDocument(database().articles[id])?.sheet?.render(true);}
}

function explainRelationships(id){const data=database(),article=data.articles[id];if(!article)return;const limit=relationshipDisplayDepth(data,article),report=relationshipDiagnostics(data,id,{descendantDisplayDepth:limit}),titleFor=value=>data.articles[value]?.title??rootLabel(value)??value,pathHtml=row=>row.path.map(value=>`<span>${esc(titleFor(value))}</span>`).join('<i class="fas fa-chevron-right" aria-hidden="true"></i>'),placementHtml=report.placements.map(row=>`<li><div class="cw-trace-path">${row.labels.map(label=>`<span>${esc(label)}</span>`).join('<i class="fas fa-chevron-right" aria-hidden="true"></i>')}</div></li>`).join(""),displayedHtml=report.displayed.map(row=>`<li><strong>${esc(titleFor(row.id))}</strong><small>${row.direction==="parent"?`Parent link stored on ${article.title}.`:row.distance===1?`Child link stored on ${titleFor(row.storedOn)}.`:`Inherited through ${titleFor(row.path.at(-2))} · ${row.distance} steps away.`}</small><div class="cw-trace-path">${pathHtml(row)}</div></li>`).join(""),suppressedHtml=report.suppressed.map(row=>`<li><strong>${esc(titleFor(row.id))}</strong><small>${row.distance} steps away · ${row.direction} · suppressed by the ${limit}-step display rule</small><div class="cw-trace-path">${pathHtml(row)}</div></li>`).join("");new Dialog({title:`Relationship Explanation — ${article.title}`,content:`<div class="cw-relationship-trace"><p>This report reads the current Article graph. It does not change any relationships.</p><section><h3>Sidebar placements</h3><ul>${placementHtml||'<li class="cw-empty">No valid sidebar path.</li>'}</ul></section><section><h3>Displayed relationships (up to ${limit} ${limit===1?"step":"steps"})</h3><ul>${displayedHtml||'<li class="cw-empty">None.</li>'}</ul></section><section><h3>Suppressed inherited relationships</h3><p>These Articles are reachable through the graph but fall beyond this Article's ${limit}-step display limit.</p><ul>${suppressedHtml||'<li class="cw-empty">None.</li>'}</ul></section></div>`,buttons:{close:{label:"Close"}}},{width:850,height:Math.min(760,window.innerHeight-80),classes:["dialog","campaign-wiki-dialog","campaign-wiki-relationship-trace-dialog"]}).render(true);}

function linkingTreeNodeHtml(node,rules){const key=node.path.join(">"),checked=pathRuleState(rules,node.path,true),category=node.article.organizer||node.children.length;return `<li data-linking-node><label><input type="checkbox" data-linking-path="${esc(key)}"${checked?" checked":""}><span>${esc(node.article.title)}</span>${category?'<small>category</small>':""}</label>${node.children.length?`<ul>${node.children.map(child=>linkingTreeNodeHtml(child,rules)).join("")}</ul>`:""}</li>`;}
