function relationshipWordingHtml(values){return `<form class="cw-wording-form"><p>Edit relationship headings without changing the relationships themselves. Blank item or Actor-child labels retain their automatic category wording.</p>${RELATIONSHIP_WORDING_FIELDS.map(([group,fields])=>`<fieldset><legend>${esc(group)}</legend>${fields.map(([key,label])=>`<label><span>${esc(label)}</span><input name="${esc(key)}" value="${esc(values[key]??"")}" placeholder="Automatic category wording"></label>`).join("")}</fieldset>`).join("")}</form>`;}
function openRelationshipWording(){const values=relationshipWording();new Dialog({title:"Campaign Wiki Custom Relationship Wording",content:relationshipWordingHtml(values),buttons:{save:{icon:'<i class="fas fa-save"></i>',label:"Save",callback:async html=>{const form=new FormData(html.find("form")[0]),next={};for(const[,fields]of RELATIONSHIP_WORDING_FIELDS)for(const[key]of fields)next[key]=String(form.get(key)??"").trim();await game.settings.set(MODULE_ID,SETTING_RELATIONSHIP_WORDING,{initialized:true,values:next});app?.render(false);ui.notifications.info("Campaign Wiki relationship wording updated.");}},defaults:{icon:'<i class="fas fa-undo"></i>',label:"Original Defaults",callback:async()=>{await game.settings.set(MODULE_ID,SETTING_RELATIONSHIP_WORDING,{initialized:true,values:{}});app?.render(false);ui.notifications.info("Original Campaign Wiki relationship wording restored.");}},cancel:{label:"Cancel"}},default:"save"},{width:720,height:Math.min(820,window.innerHeight-60),classes:["dialog","campaign-wiki-dialog","campaign-wiki-wording-dialog"]}).render(true);}
async function initializeRelationshipWording(){const stored=clone(game.settings.get(MODULE_ID,SETTING_RELATIONSHIP_WORDING)||{});if(stored.initialized)return;const existingWorld=Object.keys(database().articles??{}).length>0;await game.settings.set(MODULE_ID,SETTING_RELATIONSHIP_WORDING,{initialized:true,values:existingWorld?{...CURRENT_RELATIONSHIP_WORDING}:{}});}

function dialogForm(title,content,{width=820,height="auto",onRender}={}){return new Promise(resolve=>new Dialog({title,content:`<form class="cw-form cw-unified-form">${content}</form>`,buttons:{save:{icon:'<i class="fas fa-save"></i>',label:"Save",callback:html=>resolve(new FormData(html.find("form")[0]))},cancel:{label:"Cancel",callback:()=>resolve(null)}},default:"save",close:()=>resolve(null),render:html=>onRender?.(html)}, {width,height,classes:["dialog","campaign-wiki-dialog"]}).render(true));}
function shortestPathTo(data,parentId){if(ROOT_IDS.has(parentId))return[parentId];const parent=data.articles[parentId],role=parent?articleRole(data,parent):"",preferredRoot=role==="person"||role==="people-category"||role==="affiliation"?"root:people":role==="place"?"root:places":role==="image"||role==="image-category"?"root:images":role==="metaplot"?"root:metaplots":role==="arc"||role==="session"?"root:arcs":null;return preferredPathTo(data,parentId,preferredRoot);}
function parentPickerHtml(article){return `<fieldset class="cw-parent-picker" data-parent-picker data-article-id="${article?.id??""}" data-parents="${esc(JSON.stringify(article?.parentIds??[]))}"><legend>Parent Article Paths</legend><div data-parent-rows></div><button type="button" data-add-parent><i class="fas fa-plus"></i> Add Parent Path</button><p>Each path selects one immediate parent. An Article may appear beneath several parents.</p></fieldset>`;}
function setupParentPicker(html,data,article){const picker=html.find("[data-parent-picker]")[0],rows=picker.querySelector("[data-parent-rows]"),blocked=new Set(article?.id?[article.id,...descendantsOf(data,article.id)]:[]),validHint=(parentId,path)=>Array.isArray(path)&&path.at(-1)===parentId&&pathsTo(data,parentId).some(candidate=>JSON.stringify(candidate)===JSON.stringify(path));let states=(article?.parentIds?.length?article.parentIds:["root:people"]).map(parentId=>validHint(parentId,article?.parentPathHints?.[parentId])?[...article.parentPathHints[parentId]]:shortestPathTo(data,parentId));const render=()=>{rows.innerHTML="";states.forEach((state,index)=>{const row=document.createElement("div");row.className="cw-parent-row";const root=document.createElement("select");root.innerHTML=ROOTS.map(item=>`<option value="${item.id}"${state[0]===item.id?" selected":""}>${esc(item.name)}</option>`).join("");root.onchange=()=>{states[index]=[root.value];render();};row.append(root);for(let depth=0;depth<state.length;depth++){const parentId=state[depth],next=state[depth+1]??"",choices=childrenOf(data,parentId).filter(item=>!blocked.has(item.id)&&(item.id===next||sidebarPickerAllows(state[0],depth,articleRole(data,item)))).sort((a,b)=>a.title.localeCompare(b.title));if(!choices.length)continue;const select=document.createElement("select");select.innerHTML=`<option value="">Use ${esc(ROOT_IDS.has(parentId)?rootLabel(parentId):data.articles[parentId]?.title)} as parent</option>${choices.map(item=>`<option value="${item.id}"${next===item.id?" selected":""}>${esc(item.title)}</option>`).join("")}`;select.onchange=()=>{states[index]=state.slice(0,depth+1);if(select.value)states[index].push(select.value);render();};row.append(select);}const hidden=document.createElement("input");hidden.type="hidden";hidden.name="parentIds";hidden.value=state.at(-1);row.append(hidden);const pathHint=document.createElement("input");pathHint.type="hidden";pathHint.name="parentPathHints";pathHint.value=JSON.stringify(state);row.append(pathHint);if(states.length>1){const remove=document.createElement("button");remove.type="button";remove.innerHTML='<i class="fas fa-trash"></i>';remove.onclick=()=>{states.splice(index,1);render();};row.append(remove);}rows.append(row);});};picker.querySelector("[data-add-parent]").onclick=()=>{states.push(["root:people"]);render();};render();}
const artworkRoot=()=>`worlds/${game.world.id}/campaign-wiki`;
const artworkSource=()=>globalThis.ForgeVTT?.usingTheForge?"forgevtt":"data";
const filePickerClass=()=>globalThis.FilePicker??globalThis.foundry?.applications?.apps?.FilePicker?.implementation;
async function ensureArtworkFolders(folders){const Picker=filePickerClass(),source=artworkSource(),created=[],existing=[],failed=[];for(const folder of folders)try{await Picker.createDirectory(source,folder);created.push(folder);}catch(error){if(/exist|EEXIST|already/i.test(String(error?.message??error)))existing.push(folder);else failed.push({folder,error:String(error?.message??error)});}return{created,existing,failed};}
async function openArticleImagePicker(html,data,article){const parentIds=html.find("[name=parentIds]").map((_index,input)=>input.value).get(),draft={...article,parentIds},destinations=artworkDestinations(data,draft,artworkRoot()),destination=destinations.length===1?destinations[0]:null;if(destination)await ensureArtworkFolders(artworkFolders([{destinations:[destination]}],artworkRoot()));const options={type:"image",callback:path=>{html.find("[name=image]").val(path);html.find("[data-image-preview]").attr("src",path);}};if(destination)options.current=destination;new (filePickerClass())(options).render(true);}
function articleForm(data,article){return `<div class="cw-form-header"><img src="${esc(headerImage(article))}" alt=""><label>Article Title<input class="cw-title-input" name="title" required value="${esc(article.title)}"></label></div>${parentPickerHtml(article)}<div class="cw-form-meta"><label>Date<input type="date" name="date" value="${esc(article.date)}"></label><label>Progress<select name="status"><option value="">Not applicable</option><option value="in-progress"${article.status==="in-progress"?" selected":""}>In Progress</option><option value="complete"${article.status==="complete"?" selected":""}>Complete</option></select></label><label>Current Status<select name="currentStatus">${Object.entries(CURRENT_STATUS_LABELS).map(([value,label])=>`<option value="${value}"${(article.currentStatus||"active")===value?" selected":""}>${label}</option>`).join("")}</select></label><label>Visibility<select name="visibility"><option value="automatic"${article.visibility==="automatic"?" selected":""}>Automatic</option><option value="always-public"${article.visibility==="always-public"?" selected":""}>Always Public</option><option value="always-gm"${article.visibility==="always-gm"?" selected":""}>Always GM Only</option></select></label></div><label>Quote <span class="cw-optional">(optional)</span><textarea name="quote" rows="2">${esc(article.quote)}</textarea></label><div class="cw-form-body"><div><label>Article Image<div class="cw-file"><input name="image" value="${esc(article.image)}"><button type="button" data-file><i class="fas fa-folder-open"></i></button></div></label><img data-image-preview src="${esc(article.image||FALLBACK_LOGO)}" alt=""></div><label>Article Text<textarea name="text" rows="16">${esc(article.text)}</textarea></label></div><details><summary>Aliases</summary><label>One per line<textarea name="aliases" rows="4">${esc(article.aliases.join("\n"))}</textarea></label></details>${article.source?`<p class="cw-source"><strong>Foundry source:</strong> ${esc(article.source.uuid)}${article.source.missing?" — Missing":""}</p>`:""}`;}
async function editArticle(existing=null){const data=database(),article=normalizeArticle(existing??{id:makeArticleId(),title:"",parentIds:["root:people"],text:"",quote:"",image:"",aliases:[],visibility:VISIBILITY.AUTOMATIC,date:today(),status:"",currentStatus:"active",placeholder:false});const form=await dialogForm(existing?"Edit Article":"New Article",articleForm(data,article),{height:Math.min(760,window.innerHeight-80),onRender:html=>{setupParentPicker(html,data,article);html.on("click","[data-file]",()=>openArticleImagePicker(html,data,article));html.on("input","[name=image]",event=>html.find("[data-image-preview]").attr("src",event.currentTarget.value||FALLBACK_LOGO));}});if(!form)return;try{const current=database(),image=String(form.get("image")??"").trim(),parentIds=[...new Set(form.getAll("parentIds"))],parentPathHints=Object.fromEntries(form.getAll("parentPathHints").map(value=>JSON.parse(value)).filter(path=>path.length&&parentIds.includes(path.at(-1))).map(path=>[path.at(-1),path])),saved=putArticle(current,{...article,title:form.get("title"),parentIds,parentPathHints,date:form.get("date")||today(),status:form.get("status"),currentStatus:form.get("currentStatus"),visibility:form.get("visibility"),image,artworkIssue:article.artworkIssue?.path===image?article.artworkIssue:null,quote:form.get("quote"),text:form.get("text"),aliases:String(form.get("aliases")??"").split(/\r?\n/).map(value=>value.trim()).filter(Boolean),placeholder:false});await persist(current);app.currentId=saved.id;}catch(error){ui.notifications.error(error.message);}}
async function newChild(parentId){const data=database(),parent=data.articles[parentId];if(!parent)return;const form=await dialogForm("New Child Article",`<p>This creates a title-only placeholder beneath <strong>${esc(parent.title)}</strong> and adds it to Needs Actioning.</p><label>Article Title<input name="title" required></label>`,{width:460});if(!form)return;try{const current=database(),child=putArticle(current,{id:makeArticleId(),title:form.get("title"),parentIds:[parentId],text:"",image:"",aliases:[],visibility:VISIBILITY.AUTOMATIC,date:today(),placeholder:true});await persist(current);app.currentId=child.id;}catch(error){ui.notifications.error(error.message);}}
async function editSpecialPage({setting,title,page}){const form=await dialogForm(title,`<label>Page Title<input name="title" required value="${esc(page.title)}"></label><label>Page Image<div class="cw-file"><input name="image" value="${esc(page.image)}"><button type="button" data-file><i class="fas fa-folder-open"></i></button></div></label><img class="cw-special-page-preview" data-image-preview src="${esc(page.image||FALLBACK_LOGO)}" alt=""><label>Page Text<textarea name="text" rows="10">${esc(page.text)}</textarea></label>`,{width:680,height:"auto",onRender:html=>{html.on("click","[data-file]",()=>new FilePicker({type:"image",callback:path=>{html.find("[name=image]").val(path);html.find("[data-image-preview]").attr("src",path);}}).render(true));html.on("input","[name=image]",event=>html.find("[data-image-preview]").attr("src",event.currentTarget.value||FALLBACK_LOGO));}});if(!form)return;await game.settings.set(MODULE_ID,setting,{title:String(form.get("title")||page.title).trim(),image:String(form.get("image")||"").trim(),text:String(form.get("text")||"")});app?.render(false);ui.notifications.info(`${title.replace(/^Edit /,"")} updated.`);}
const editUnavailablePage=()=>editSpecialPage({setting:SETTING_UNAVAILABLE,title:"Edit Player Unavailable Page",page:unavailablePage()});
const editHomePage=()=>editSpecialPage({setting:SETTING_HOME,title:"Edit Campaign Wiki Home Page",page:homePage()});
async function deleteArticle(id){const data=database(),article=data.articles[id];if(!article)return;const children=childrenOf(data,id);if(!await confirmAction(`Delete ${article.title}?`,`${children.length} child Article(s) will inherit this Article's parents. The Foundry source will not be deleted.`))return;for(const child of children)child.parentIds=[...new Set([...child.parentIds.filter(parentId=>parentId!==id),...article.parentIds])];removeArticle(data,id);await persist(data);app.currentId=null;}
function confirmAction(title,content){return new Promise(resolve=>new Dialog({title,content:`<p>${esc(content)}</p>`,buttons:{yes:{label:"Confirm",callback:()=>resolve(true)},no:{label:"Cancel",callback:()=>resolve(false)}},default:"no",close:()=>resolve(false)}).render(true));}

function saveBlob(data,type,name){const url=URL.createObjectURL(new Blob([data],{type})),anchor=document.createElement("a");anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function pickerTarget(value,root=artworkRoot()){return pathWithinRoot(value,root)??String(value??"").replace(/^\/+|\/+$/g,"");}
async function browseArtworkFolder(target){return filePickerClass().browse(artworkSource(),target);}
async function listArtworkFiles(){const root=artworkRoot(),queue=[root],visited=new Set(),files=[];while(queue.length){const target=queue.shift();if(visited.has(target))continue;visited.add(target);let result;try{result=await browseArtworkFolder(target);}catch{continue;}for(const file of result.files??[])files.push(file);for(const directory of result.dirs??[]){const child=pickerTarget(directory,root);if(child&&child.toLocaleLowerCase().startsWith(root.toLocaleLowerCase())&&!visited.has(child))queue.push(child);}}return files;}
async function unrepresentedArtwork(data=database()){const allWikiArtwork=[...Object.values(data.articles).flatMap(article=>[article.image,article.tokenImage]),homePage().image,unavailablePage().image],represented=representedArtworkPaths(buildArtworkPlan(data,artworkRoot()),artworkRoot(),allWikiArtwork),allFiles=await listArtworkFiles();return allFiles.map(file=>pathWithinRoot(file,artworkRoot())).filter(path=>path&&!represented.has(path.toLocaleLowerCase()));}
function artworkPlanHtml(plan){const ready=plan.filter(row=>row.status==="ready").length,attention=plan.length-ready;return `<p><strong>${ready}</strong> artwork move(s) have one clear sidebar-derived destination. <strong>${attention}</strong> require review.</p><p>Campaign Wiki will create folders and repair links, but use Forge's <strong>Move</strong> control to move the files themselves.</p><div class="cw-artwork-plan"><table><thead><tr><th>Article</th><th>Current artwork</th><th>Destination</th><th>Status</th></tr></thead><tbody>${plan.map(row=>`<tr><td>${esc(row.title)}</td><td title="${esc(row.current)}">${esc(row.filename)}</td><td>${esc(row.destination??row.destinations.join(" or "))}</td><td>${esc(row.status==="ready"?"Ready":row.status==="ambiguous-path"?"Choose one sidebar path":"Duplicate filename")}</td></tr>`).join("")}</tbody></table></div>`;}
function showArtworkResults(title,summary,items=[]){new Dialog({title,content:`<div class="cw-artwork-results"><p>${summary}</p>${items.length?`<h3>Needs your attention</h3><ul>${items.map(item=>`<li>${esc(item)}</li>`).join("")}</ul>`:'<p class="cw-empty">Nothing requires manual attention.</p>'}</div>`,buttons:{close:{label:"Close"}}},{width:760,classes:["dialog","campaign-wiki-dialog"]}).render(true);}
async function createArtworkFolders(){const data=database(),plan=buildArtworkPlan(data,artworkRoot()),result=await ensureArtworkFolders(artworkFolders(plan,artworkRoot()));showArtworkResults("Campaign Wiki Artwork Folders",`Created ${result.created.length} folder(s); ${result.existing.length} already existed.`,result.failed.map(item=>`${item.folder}: ${item.error}`));}
async function flagUnrepresentedArtwork(files){const data=database(),created=[];for(const path of files){const article=putArticle(data,{id:makeArticleId(),title:titleFromArtworkPath(path),parentIds:[sidebarParentForArtworkPath(data,path,artworkRoot())],text:"",image:path,aliases:[],visibility:VISIBILITY.AUTOMATIC,date:today(),placeholder:true});created.push(article.title);}await persist(data);showArtworkResults("Artwork Added to Needs Actioning",`${created.length} placeholder Image Article(s) were created in their matching sidebar categories. The artwork files were not moved or changed.`,created);}
async function scanUnrepresentedArtwork(){const files=await unrepresentedArtwork(),summary=`${files.length} file(s) beneath ${artworkRoot()} are neither referenced anywhere in Campaign Wiki nor matched to a planned Images destination.`;new Dialog({title:"Unrepresented Campaign Wiki Artwork",content:`<div class="cw-artwork-results"><p>${esc(summary)}</p>${files.length?`<h3>Needs your attention</h3><ul>${files.map(path=>`<li>${esc(path)}</li>`).join("")}</ul>`:'<p class="cw-empty">Nothing requires manual attention.</p>'}</div>`,buttons:{flag:{icon:'<i class="fas fa-flag"></i>',label:"Flag in Needs Actioning",callback:()=>flagUnrepresentedArtwork(files)},close:{label:"Close"}},default:"close"},{width:760,classes:["dialog","campaign-wiki-dialog"]}).render(true);}
const bytesToHex=bytes=>[...new Uint8Array(bytes)].map(value=>value.toString(16).padStart(2,"0")).join("");
async function hashArtworkFile(path){const response=await fetch(path,{cache:"no-store"});if(!response.ok)throw new Error(`${response.status} ${response.statusText}`);const content=await response.arrayBuffer();return{path,size:content.byteLength,hash:bytesToHex(await crypto.subtle.digest("SHA-256",content))};}
async function auditArtworkDuplicates(){const data=database(),plan=buildArtworkPlan(data,artworkRoot()),paths=await listArtworkFiles(),hashed=new Array(paths.length),failures=[];ui.notifications.info(`Campaign Wiki is hashing ${paths.length} artwork file(s). This may take a while.`);let next=0;const worker=async()=>{while(next<paths.length){const index=next++,path=paths[index];try{hashed[index]=await hashArtworkFile(path);}catch(error){failures.push({path:pathWithinRoot(path,artworkRoot())??path,error:String(error?.message??error)});}}};await Promise.all(Array.from({length:Math.min(4,paths.length)},worker));const analysis=analyzeArtworkDuplicates(hashed.filter(Boolean),plan,artworkRoot()),report={generatedAt:new Date().toISOString(),worldId:game.world.id,root:artworkRoot(),...analysis,hashFailures:failures};saveBlob(JSON.stringify(report,null,2),"application/json",`${slug(game.world.title)}-campaign-wiki-duplicate-audit-${today()}.json`);const duplicateSummary=group=>group.status==="planned-canonical-missing"?`Planned canonical destination (not yet present): ${group.canonical.join(", ")} — identical source copies: ${group.sources.join(", ")}`:group.status==="ambiguous"?`Choose a canonical copy: ${group.members.join(", ")}`:`Canonical: ${group.canonical.join(", ")} — redundant copy candidate(s): ${group.redundant.join(", ")||"none"}`,items=[...analysis.duplicateGroups.map(duplicateSummary),...analysis.filenameConflicts.map(conflict=>`Same filename, different content: ${conflict.files.map(file=>file.path).join(", ")}`),...failures.map(failure=>`Could not hash ${failure.path}: ${failure.error}`)];showArtworkResults("Campaign Wiki Duplicate Artwork Audit",`Found ${analysis.duplicateGroups.length} exact duplicate group(s) and ${analysis.filenameConflicts.length} same-name content conflict(s). The full checksum report was downloaded. No files were changed or deleted.`,items);}
async function verifyArtworkMoves(){const data=database(),plan=buildArtworkPlan(data,artworkRoot()),cache=new Map(),updated=[],issues=[];exportPackage(data);for(const row of plan){const article=data.articles[row.articleId];if(row.status!=="ready"){article.artworkIssue={path:article.image,expectedPath:row.destinations.join(" or "),reason:row.status==="ambiguous-path"?"Artwork has more than one Images sidebar path.":"More than one Article resolves to the same destination filename."};issues.push(`${article.title}: ${article.artworkIssue.reason}`);continue;}let files=cache.get(row.destination);if(!files){try{files=(await browseArtworkFolder(row.destination)).files??[];}catch{files=[];}cache.set(row.destination,files);}const matches=files.filter(file=>assetFilename(file).toLocaleLowerCase()===row.filename.toLocaleLowerCase());if(matches.length===1){article.image=matches[0];article.artworkIssue=null;updated.push(article.title);}else{article.artworkIssue={path:article.image,expectedPath:`${row.destination}/${row.filename}`,reason:matches.length?"More than one matching file was found.":"Artwork was not found in its expected sidebar folder."};issues.push(`${article.title}: ${article.artworkIssue.reason}`);}}
  await persist(data);const unclassified=await unrepresentedArtwork(data);showArtworkResults("Artwork Verification Complete",`Updated ${updated.length} Campaign Wiki link(s). ${issues.length} Article(s) were added to Needs Actioning as Missing Artwork.`,[...issues,...unclassified.map(path=>`Unrepresented file: ${path}`)]);}
function openArtworkOrganizer(){const data=database(),plan=buildArtworkPlan(data,artworkRoot());new Dialog({title:"Campaign Wiki Artwork Organizer",content:artworkPlanHtml(plan),buttons:{download:{icon:'<i class="fas fa-download"></i>',label:"Export Move Plan",callback:()=>saveBlob(JSON.stringify({generatedAt:new Date().toISOString(),worldId:game.world.id,root:artworkRoot(),moves:plan},null,2),"application/json",`${slug(game.world.title)}-campaign-wiki-artwork-plan-${today()}.json`)},folders:{icon:'<i class="fas fa-folder-plus"></i>',label:"Create Folders",callback:()=>createArtworkFolders()},duplicates:{icon:'<i class="fas fa-copy"></i>',label:"Audit Duplicates",callback:()=>auditArtworkDuplicates()},scan:{icon:'<i class="fas fa-search"></i>',label:"Find Unrepresented",callback:()=>scanUnrepresentedArtwork()},verify:{icon:'<i class="fas fa-check-double"></i>',label:"Verify & Repair",callback:()=>verifyArtworkMoves()},cancel:{label:"Close"}},default:"cancel"},{width:1100,height:Math.min(760,window.innerHeight-80),classes:["dialog","campaign-wiki-dialog","campaign-wiki-artwork-dialog"]}).render(true);}
function exportPackage(data=database()){saveBlob(JSON.stringify({format:"campaign-wiki-unified",version:3,exportedAt:new Date().toISOString(),database:data},null,2),"application/json",`${slug(game.world.title)}-campaign-wiki-${today()}.json`);}
function importPackage(){const input=document.createElement("input");input.type="file";input.accept=".json,application/json";input.onchange=async()=>{try{const payload=JSON.parse(await input.files[0].text()),incoming=payload.database??payload,errors=validateUnified(incoming);if(errors.length)throw new Error(errors.join("\n"));exportPackage();await persist(incoming);ui.notifications.info("Campaign Wiki imported after automatic backup.");}catch(error){ui.notifications.error(error.message);}};input.click();}
async function offerV2Migration(){const current=database();if(Object.keys(current.articles).length||current.migration)return;let v2;try{v2=game.settings.get(MODULE_ID,SETTING_V2);}catch{return;}if(!v2?.entities||!Object.keys(v2.entities).length)return;if(!await confirmAction("Create unified Campaign Wiki?","Your v2 data will be downloaded unchanged, then converted conservatively into the unified multi-parent Article model. The v2 world setting and legacy overlay remain untouched."))return;saveBlob(JSON.stringify(v2,null,2),"application/json",`${slug(game.world.title)}-campaign-wiki-v2-backup-${today()}.json`);const result=migrateV2(v2,game.world.id);await persist(result.database);ui.notifications.info(`Created ${result.stats.articles} Articles and ${result.stats.parentLinks} exact parent links. Unfinished placeholders are in Needs Actioning.`);}

function sourceArticle(data,documentType,id){return articles(data).find(article=>article.source?.documentType===documentType&&article.source.id===id);}
function actorQuote(document){return String(document?.system?.CHARACTER?.CHARACTER_INFO?.QUOTE??document?.system?.quote??"").replace(/<[^>]*>/g,"").trim();}
async function createSourceArticle(documentType,document){if(!game.user.isGM)return;const data=database();if(sourceArticle(data,documentType,document.id))return;putArticle(data,{id:makeArticleId(),title:document.name,parentIds:[documentType==="Actor"?"root:people":"root:places"],text:"",quote:documentType==="Actor"?actorQuote(document):"",image:documentType==="Actor"?document.img:(document.background?.src||document.img||""),tokenImage:documentType==="Actor"?(document.prototypeToken?.texture?.src||""):"",aliases:[],visibility:VISIBILITY.AUTOMATIC,date:today(),placeholder:true,source:{documentType,uuid:document.uuid,id:document.id,missing:false}});await persist(data);}
async function syncSource(documentType,document){if(!game.user.isGM)return;const data=database(),article=sourceArticle(data,documentType,document.id);if(!article)return;if(article.title!==document.name){article.aliases=[...new Set([...article.aliases,article.title])];article.title=document.name;}article.image=documentType==="Actor"?document.img:(document.background?.src||document.img||"");if(documentType==="Actor"){article.tokenImage=document.prototypeToken?.texture?.src||"";article.quote||=actorQuote(document);}article.source.missing=false;await persist(data);}
async function backfillActorQuotes(){if(!game.user.isGM)return;const data=database();let changed=false;for(const article of articles(data)){if(article.quote||article.source?.documentType!=="Actor")continue;const quote=actorQuote(game.actors.get(article.source.id));if(quote){article.quote=quote;changed=true;}}if(changed)await persist(data);}
async function missingSource(documentType,document){if(!game.user.isGM)return;const data=database(),article=sourceArticle(data,documentType,document.id);if(article){article.source.missing=true;await persist(data);}}

function installLauncher(){let launcher=document.querySelector("#campaign-wiki-launcher");if(!launcher){launcher=document.createElement("button");launcher.id="campaign-wiki-launcher";launcher.type="button";launcher.innerHTML='<i class="fas fa-book-open"></i><span>Campaign Wiki</span>';launcher.onclick=openWiki;document.body.append(launcher);}positionLauncher();}
function positionLauncher(){const launcher=document.querySelector("#campaign-wiki-launcher"),players=document.querySelector("#players"),rect=players?.getBoundingClientRect();if(!launcher)return;const hasPlayers=rect&&rect.width>0&&rect.height>0;launcher.style.left=hasPlayers?`${Math.max(8,Math.round(rect.left))}px`:"12px";launcher.style.bottom=hasPlayers?`${Math.max(8,Math.round(window.innerHeight-rect.top+8))}px`:"12px";}
function openWiki(){app??=new CampaignWikiApp();app.currentId=null;app.currentPath=null;app.query="";app.playerPreview=false;app.openNavigation.clear();app.expandedRelationshipGroups.clear();app.render(true);}
class OpenMenu extends FormApplication{render(){openWiki();return this;}}class HomePageMenu extends FormApplication{render(){editHomePage();return this;}}class UnavailableMenu extends FormApplication{render(){editUnavailablePage();return this;}}class LinkingCategoriesMenu extends FormApplication{render(){openLinkingCategories();return this;}}class RelationshipWordingMenu extends FormApplication{render(){openRelationshipWording();return this;}}class ArtworkOrganizerMenu extends FormApplication{render(){openArtworkOrganizer();return this;}}class ExportMenu extends FormApplication{render(){exportPackage();return this;}}class ImportMenu extends FormApplication{render(){importPackage();return this;}}

Hooks.once("init",()=>{game.settings.register(MODULE_ID,SETTING_DATABASE,{scope:"world",config:false,type:Object,default:emptyUnifiedDatabase()});game.settings.register(MODULE_ID,SETTING_V2,{scope:"world",config:false,type:Object,default:{}});game.settings.register(MODULE_ID,SETTING_HOME,{scope:"world",config:false,type:Object,default:{...DEFAULT_HOME}});game.settings.register(MODULE_ID,SETTING_UNAVAILABLE,{scope:"world",config:false,type:Object,default:{...DEFAULT_UNAVAILABLE}});game.settings.register(MODULE_ID,SETTING_AUTO_LINKS,{name:"Automatic Article Linking",hint:"Turn first-mention links from Article text to selected Wiki content on or off. Hidden Articles are never linked for players.",scope:"world",config:true,type:Boolean,default:true,onChange:()=>app?.render(false)});game.settings.register(MODULE_ID,SETTING_LINK_DEPTH,{scope:"world",config:false,type:String,default:"2"});game.settings.register(MODULE_ID,SETTING_LINK_CATEGORIES,{scope:"world",config:false,type:Object,default:{}});game.settings.register(MODULE_ID,SETTING_RELATIONSHIP_WORDING,{scope:"world",config:false,type:Object,default:{initialized:false,values:{}}});for(const[rootId,key]of Object.entries(SORT_SETTINGS))game.settings.register(MODULE_ID,key,{name:`${rootLabel(rootId)} Sidebar Sort Order`,hint:`Choose how Articles beneath ${rootLabel(rootId)} are ordered in Campaign Wiki navigation.`,scope:"world",config:true,type:String,choices:SORT_CHOICES,default:rootId==="root:metaplots"||rootId==="root:arcs"?"date-desc":"alpha-asc",onChange:()=>app?.render(false)});for(const[rootId,key]of Object.entries(RELATIONSHIP_DEPTH_SETTINGS))game.settings.register(MODULE_ID,key,{name:`${rootLabel(rootId)} Relationship Display Depth`,hint:`Choose how many descendant relationship steps appear on Articles in ${rootLabel(rootId)}. This does not affect visibility or sidebar placement.`,scope:"world",config:true,type:String,choices:RELATIONSHIP_DEPTH_CHOICES,default:rootId==="root:metaplots"?"2":"1",onChange:()=>app?.render(false)});game.settings.registerMenu(MODULE_ID,"openWiki",{name:"Open Campaign Wiki",label:"Open",hint:"Open Campaign Wiki on Home.",icon:"fas fa-book-open",type:OpenMenu,restricted:false});game.settings.registerMenu(MODULE_ID,"homePage",{name:"Campaign Wiki Home Page",label:"Edit Page",hint:"Customize the Home page title, image, and introductory text.",icon:"fas fa-home",type:HomePageMenu,restricted:true});game.settings.registerMenu(MODULE_ID,"unavailablePage",{name:"Player Unavailable Page",label:"Edit Page",hint:"Customize what players see when a Campaign Wiki Article is hidden.",icon:"fas fa-eye-slash",type:UnavailableMenu,restricted:true});game.settings.registerMenu(MODULE_ID,"linkingCategories",{name:"Campaign Wiki Article Linking Categories",label:"Choose Categories",hint:"Choose which sidebar branches supply automatic Article links.",icon:"fas fa-link",type:LinkingCategoriesMenu,restricted:true});game.settings.registerMenu(MODULE_ID,"relationshipWording",{name:"Campaign Wiki Custom Relationship Wording",label:"Edit Wording",hint:"Customize relationship headings without changing Article relationships.",icon:"fas fa-pen",type:RelationshipWordingMenu,restricted:true});game.settings.registerMenu(MODULE_ID,"artworkOrganizer",{name:"Campaign Wiki Artwork Organizer",label:"Organize Artwork",hint:"Create sidebar-matched folders, export a Forge move plan, repair moved artwork links, and report anything unclassified.",icon:"fas fa-images",type:ArtworkOrganizerMenu,restricted:true});game.settings.registerMenu(MODULE_ID,"exportWiki",{name:"Export Campaign Wiki",label:"Export",hint:"Download this world's unified Campaign Wiki.",icon:"fas fa-download",type:ExportMenu,restricted:true});game.settings.registerMenu(MODULE_ID,"importWiki",{name:"Import Campaign Wiki",label:"Import",hint:"Back up and replace this world's unified Campaign Wiki.",icon:"fas fa-upload",type:ImportMenu,restricted:true});game.modules.get(MODULE_ID).api={open:openWiki,getDatabase:database,put:async input=>{const data=database(),result=putArticle(data,input);await persist(data);return result;},export:exportPackage};});
Hooks.once("ready",async()=>{ui.campaignWiki={open:openWiki,render:openWiki};installLauncher();window.addEventListener("resize",positionLauncher);if(game.user.isGM){await offerV2Migration();await initializeRelationshipWording();await backfillActorQuotes();}});Hooks.on("renderSidebar",installLauncher);Hooks.on("collapseSidebar",()=>setTimeout(positionLauncher,100));Hooks.on("createActor",document=>createSourceArticle("Actor",document));Hooks.on("createScene",document=>createSourceArticle("Scene",document));Hooks.on("updateActor",document=>syncSource("Actor",document));Hooks.on("updateScene",document=>syncSource("Scene",document));Hooks.on("deleteActor",document=>missingSource("Actor",document));Hooks.on("deleteScene",document=>missingSource("Scene",document));
